import { Audio } from 'expo-av';

const B64 = {
  dk_jump: '',
  dk_land: '',
  dk_death: '',
  dk_win: '',
  dk_score: '',
  dk_barrel: '',
  dk_intro: '',
};
const loaded = {};

async function load(name) {
  if (loaded[name]) return loaded[name];
  const { sound } = await Audio.Sound.createAsync({ uri: `data:audio/wav;base64,${B64[name]}` });
  loaded[name] = sound;
  return sound;
}

export async function preloadDKSounds() {
  await Audio.setAudioModeAsync({ playsInSilentModeIOS: true });
  await Promise.all(Object.keys(B64).map(load));
}

export async function playDKSound(name) {
  try {
    const snd = await load(name);
    await snd.setPositionAsync(0);
    await snd.playAsync();
  } catch (_) {}
}

export async function unloadDKSounds() {
  for (const s of Object.values(loaded)) { try { await s.unloadAsync(); } catch (_) {} }
  Object.keys(loaded).forEach(k => delete loaded[k]);
}
